import json
import yaml
from pathlib import Path

def yaml_to_json(yaml_file_path: str) -> str:
    try:
        # Sanitize the file path to prevent path traversal attacks
        file_path = Path(yaml_file_path).resolve()
        if not file_path.parent == Path("allowed/directory"):
            raise PermissionError("Access to the specified path is denied.")

        with open(file_path, 'r') as file:
            # Use safe_load to prevent arbitrary code execution
            yaml_content = yaml.safe_load(file)

            # Convert YAML content to JSON string
            json_content = json.dumps(yaml_content)
            return json_content

    except FileNotFoundError:
        return "Error: File not found."
    except PermissionError as e:
        return f"Error: {str(e)}"
    except yaml.YAMLError as e:
        return "Error: Invalid YAML content."
    except TypeError:
        return "Error: Cannot convert YAML to JSON."
    except Exception as e:
        return "Error: An unexpected error occurred."

